package main

import (
	"fmt"
	"runtime"
)

func main() {
	var m runtime.MemStats

	// Allocate ~1M small objects so there is something to collect.
	junk := make([][]byte, 0, 1000)
	for i := 0; i < 1000; i++ {
		junk = append(junk, make([]byte, 1024)) // 1 KiB each
	}
	runtime.GC() // force a cycle so counters are meaningful

	runtime.ReadMemStats(&m)
	fmt.Printf("NumGC=%d\n", m.NumGC)            // number of completed cycles
	fmt.Printf("HeapAlloc=%d KiB\n", m.HeapAlloc/1024) // live + not-yet-swept bytes
	fmt.Printf("NextGC=%d KiB\n", m.NextGC/1024)       // pacer's heap goal

	// Drop the references and collect again: the heap goal shifts down.
	junk = nil
	runtime.GC()
	runtime.ReadMemStats(&m)
	fmt.Printf("after release NumGC=%d\n", m.NumGC)
}

