package solution

import (
	"bytes"
	"sync"
)

// A pool of reusable buffers. New is called only when the pool is empty.
var bufPool = sync.Pool{
	New: func() any { return new(bytes.Buffer) },
}

func Render(parts []string) string {
	buf := bufPool.Get().(*bytes.Buffer) // reuse an existing buffer if available
	buf.Reset()                          // clear any leftover bytes from prior use
	defer bufPool.Put(buf)               // return it for the next caller

	for _, p := range parts {
		buf.WriteString(p) // append into the reused backing array
	}
	return buf.String() // copies bytes out, so it's safe to recycle buf
}

