func TestRender(t *testing.T) {
	cases := [][]string{
		{"a", "b", "c"},
		{},
		{"hello", " ", "world"},
		{"x"},
	}
	for _, parts := range cases {
		want := strings.Join(parts, "")
		// Call twice to exercise buffer reuse from the pool.
		if got := Render(parts); got != want {
			t.Errorf("Render(%v)=%q want %q", parts, got, want)
		}
		if got := Render(parts); got != want {
			t.Errorf("reuse Render(%v)=%q want %q", parts, got, want)
		}
	}
}

